const beforeNavigation=render;document.querySelector('nav').innerHTML=[['home','◫ Моё хозяйство'],['market','◈ Маркет'],['orders','☷ Дела'],['notifications','◉ События'],['settings','◎ Профиль']].map(([r,t])=>`<a href="#${r}">${t}</a>`).join('');
render=function(){beforeNavigation();const r=location.hash.slice(1)||'home';const farmRoutes=['home','rent','planner','journal','harvest','warehouse','guide','animals'];if(farmRoutes.includes(r)){$('#app').insertAdjacentHTML('afterbegin',`<div class="context-tabs">${[['home','Обзор'],['rent','＋ Грядка'],['planner','Посадки'],['journal','Дневник'],['harvest','Урожай'],['warehouse','Запасы'],['guide','Помощник']].map(([k,t])=>`<a class="${k===r?'selected':''}" href="#${k}">${t}</a>`).join('')}</div>`)}if(account?.role==='admin'&&['settings','farmer','services','launch','orders'].includes(r)){$('#app').insertAdjacentHTML('afterbegin','<div class="context-tabs"><a href="#farmer">Управление фермой</a><a href="#services">Тарифы</a><a href="#orders">Очередь работ</a><a href="#launch">Готовность запуска</a></div>')}document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+(farmRoutes.includes(r)?'home':r)));};render();
